 const actions=[['acknowledge','Acknowledge','Record that the alert has been reviewed.'],['assign','Assign','Assign the alert to an authorized analyst.'],['investigate','Investigate','Move status to INVESTIGATING.'],['resolve','Resolve','Move status to RESOLVED.'],['false_positive','False positive','Move status to FALSE_POSITIVE.']];
