function PredictionConsole({onCreated}){
 const [form,setForm]=useState({dataset:'nsl-kdd',task:'binary',model:'random_forest',features:'{}',generate_shap:true,generate_lime:true});
 const [busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState(null);
 const submit=async(e)=>{e.preventDefault();setBusy(true);setError('');setResult(null);try{let features;try{features=JSON.parse(form.features)}catch{throw new Error('Features must be valid JSON.')}if(!features||typeof features!=='object'||Array.isArray(features)||!Object.keys(features).length)throw new Error('Provide at least one network feature.');const r=await api.post('/predict',{dataset:form.dataset,task:form.task,model:form.model,features,generate_shap:form.generate_shap,generate_lime:form.generate_lime});setResult(r.data);onCreated?.(r.data.detection_id)}catch(e){setError(e.response?.data?.detail||e.message||'Prediction failed.')}finally{setBusy(false)}};
 return <section className="rounded-xl border border-slate-800 bg-slate-900 p-5"><div><h2 className="font-semibold">Submit network-feature input</h2><p className="mt-1 text-sm text-slate-500">Uses the selected trained model and its saved dataset preprocessor. No client-side prediction is performed.</p></div><form onSubmit={submit} className="mt-5 space-y-4"><div className="grid gap-3 md:grid-cols-3"><select value={form.dataset} onChange={e=>setForm({...form,dataset:e.target.value})} className="rounded-lg border border-slate-700 bg-slate-800 px-3 py-2 text-sm"><option value="cicids2017">CICIDS2017</option><option value="cicids2018">CSE-CIC-IDS2018</option><option value="nsl-kdd">NSL-KDD</option></select><select value={form.task} onChange={e=>setForm({...form,task:e.target.value})} className="rounded-lg border border-slate-700 bg-slate-800 px-3 py-2 text-sm"><option value="binary">Binary</option><option value="multiclass">Multiclass</option></select><select value={form.model} onChange={e=>setForm({...form,model:e.target.value})} className="rounded-lg border border-slate-700 bg-slate-800 px-3 py-2 text-sm"><option value="random_forest">Random Forest</option><option value="xgboost">XGBoost</option></select></div><textarea value={form.features} onChange={e=>setForm({...form,features:e.target.value})} rows={8} className="w-full rounded-lg border border-slate-700 bg-slate-800 px-3 py-3 font-mono text-xs" placeholder='{"duration": 0, "protocol_type": "tcp", ...}'/><div className="flex flex-wrap gap-4 text-sm text-slate-400"><label className="flex items-center gap-2"><input type="checkbox" checked={form.generate_shap} onChange={e=>setForm({...form,generate_shap:e.target.checked})}/> Generate SHAP</label><label className="flex items-center gap-2"><input type="checkbox" checked={form.generate_lime} onChange={e=>setForm({...form,generate_lime:e.target.checked})}/> Generate LIME</label><button disabled={busy} className="ml-auto rounded-lg bg-cyan-600 px-5 py-2 font-semibold text-white disabled:opacity-50">{busy?'Running pipeline…':'Run detection'}</button></div></form>{error&&<div className="mt-4 rounded-lg border border-red-900 bg-red-950/30 p-4 text-sm text-red-300">{error}</div>}{result&&<div className="mt-4 rounded-lg border border-emerald-900 bg-emerald-950/20 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="text-xs uppercase tracking-wider text-emerald-400">Detection created</div><div className="mt-1 font-semibold">{result.prediction} · {(Number(result.probability)*100).toFixed(2)}%</div><div className="mt-1 font-mono text-xs text-slate-500">{result.detection_id}</div></div><button type="button" onClick={()=>onCreated?.(result.detection_id)} className="rounded-lg border border-emerald-700 px-4 py-2 text-sm hover:bg-emerald-900/30">Open details</button></div><div className="mt-3 text-xs text-slate-400">SHAP: {result.explanation?.shap||'not requested'} · LIME: {result.explanation?.lime||'not requested'}</div></div>}</section>
}
