function ModelsPage(){
 const [items,setItems]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{api.get('/models').then(r=>setItems(r.data.items||[])).catch(e=>setError(e.response?.data?.detail||'Unable to load trained models.')).finally(()=>setLoading(false))},[]);
 return <div className="space-y-5"><header><div className="text-xs uppercase tracking-[.2em] text-cyan-400">AI-CTDRS / Model Registry</div><h1 className="mt-1 text-2xl font-bold">AI Models</h1><p className="mt-1 text-sm text-slate-500">Measured model runs published by the training pipeline. Metrics are not invented when artifacts are absent.</p></header><PageState loading={loading} error={error} empty={!items.length?'No trained model artifacts are currently published.':null}><DataTable><table className="min-w-[950px] w-full text-sm"><thead><tr className="border-b border-slate-800 text-left text-xs uppercase text-slate-500"><th className="px-4 py-3">Dataset</th><th className="px-4 py-3">Task</th><th className="px-4 py-3">Model</th><th className="px-4 py-3">Accuracy</th><th className="px-4 py-3">Precision</th><th className="px-4 py-3">Recall</th><th className="px-4 py-3">F1</th><th className="px-4 py-3">ROC-AUC</th></tr></thead><tbody>{items.map((x,i)=><tr key={`${x.run_id||'run'}-${i}`} className="border-b border-slate-800/70"><td className="px-4 py-3">{x.dataset}</td><td className="px-4 py-3">{x.task}</td><td className="px-4 py-3 font-medium">{x.model}</td>{['accuracy','precision','recall','f1_score','roc_auc'].map(k=><td key={k} className="px-4 py-3">{x.metrics?.[k]==null?'—':Number(x.metrics[k]).toFixed(4)}</td>)}</tr>)}</tbody></table></DataTable></PageState></div>
}
function ExplainableAIPage(){
 const [models,setModels]=useState([]),[selected,setSelected]=useState(''),[data,setData]=useState(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);
 useEffect(()=>{api.get('/models').then(r=>{const rows=r.data.items||[];const tree=rows.filter(x=>['random_forest','xgboost'].includes(x.model));setModels(tree);if(tree[0])setSelected(`${tree[0].dataset}|${tree[0].task}|${tree[0].model}`)}).catch(e=>setError(e.response?.data?.detail||'Unable to load model registry.')).finally(()=>setLoading(false))},[]);
 useEffect(()=>{if(!selected)return;const [dataset,task,model]=selected.split('|');setData(null);setError('');api.get('/explain/shap/global',{params:{dataset,task,model}}).then(r=>setData(r.data)).catch(e=>setError(e.response?.data?.detail||'Global SHAP has not been generated for this model run.'))},[selected]);
 return <div className="space-y-5"><header><div className="text-xs uppercase tracking-[.2em] text-cyan-400">AI-CTDRS / Explainability</div><h1 className="mt-1 text-2xl font-bold">Explainable AI</h1><p className="mt-1 text-sm text-slate-500">Global feature importance is calculated from real SHAP artifacts generated during model training.</p></header>{loading?<Empty>Loading model registry…</Empty>:!models.length?<Empty>No Random Forest or XGBoost artifacts with SHAP support are published.</Empty>:<><select aria-label="SHAP model" value={selected} onChange={e=>setSelected(e.target.value)} className="w-full max-w-xl rounded-lg border border-slate-700 bg-slate-800 px-3 py-2 text-sm">{models.map(x=><option key={`${x.dataset}|${x.task}|${x.model}`} value={`${x.dataset}|${x.task}|${x.model}`}>{x.dataset} · {x.task} · {x.model}</option>)}</select>{error?<div role="alert" className="rounded-xl border border-amber-900 bg-amber-950/20 p-5 text-sm text-amber-300">{error}</div>:data&&<><div className="grid gap-3 sm:grid-cols-3"><Metric label="Model" value={data.model}/><Metric label="Explainer" value={data.explainer}/><Metric label="Rows explained" value={data.n_samples}/></div><ContributionChart rows={(data.feature_importance||[]).map(x=>({feature_name:x.feature_name,mean_abs_shap:x.mean_abs_shap}))} keyName="mean_abs_shap" label="Mean |SHAP|"/></>}</>}</div>
}
function AnalyticsPage(){
 const [data,setData]=useState(null),[error,setError]=useState('');useEffect(()=>{api.get('/dashboard').then(r=>setData(r.data)).catch(e=>setError(e.response?.data?.detail||'Unable to load analytics.'))},[]);
 return <div className="space-y-5"><header><div className="text-xs uppercase tracking-[.2em] text-cyan-400">AI-CTDRS / Analytics</div><h1 className="mt-1 text-2xl font-bold">Analytics</h1><p className="mt-1 text-sm text-slate-500">Operational trends from persisted detections and alerts.</p></header>{error?<div role="alert" className="rounded-xl border border-red-900 bg-red-950/30 p-5 text-sm text-red-300">{error}</div>:!data?<Empty>Loading analytics…</Empty>:<><section className="rounded-xl border border-slate-800 bg-slate-900 p-5"><h2 className="font-semibold">Detection trend</h2><div className="mt-4 h-72"><ResponsiveContainer><AreaChart data={data.detection_trend||[]}><CartesianGrid strokeDasharray="3 3" stroke="#1e293b"/><XAxis dataKey="date" tick={{fill:'#94a3b8',fontSize:11}}/><YAxis allowDecimals={false} tick={{fill:'#94a3b8',fontSize:11}}/><Tooltip/><Area type="monotone" dataKey="detections" stroke="#22d3ee" fill="#22d3ee" fillOpacity={0.12}/></AreaChart></ResponsiveContainer></div></section><section className="rounded-xl border border-slate-800 bg-slate-900 p-5"><h2 className="font-semibold">Predicted classes</h2>{data.attack_distribution?.length?<div className="mt-4 h-80"><ResponsiveContainer><BarChart data={data.attack_distribution}><CartesianGrid strokeDasharray="3 3" stroke="#1e293b"/><XAxis dataKey="attack" tick={{fill:'#94a3b8',fontSize:10}}/><YAxis allowDecimals={false} tick={{fill:'#94a3b8',fontSize:11}}/><Tooltip/><Bar dataKey="count" fill="#22d3ee" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div>:<Empty>No prediction events are available for analysis.</Empty>}</section></>}</div>
}
function SettingsPage(){return <div className="space-y-5"><header><div className="text-xs uppercase tracking-[.2em] text-cyan-400">AI-CTDRS / Configuration</div><h1 className="mt-1 text-2xl font-bold">Settings</h1><p className="mt-1 text-sm text-slate-500">Operational configuration is environment-managed; secrets are never displayed in the browser.</p></header><div className="grid gap-4 md:grid-cols-2"><Metric label="API mode" value="Authenticated production API"/><Metric label="Response mode" value="SIMULATION"/><Metric label="JWT algorithm" value="HS256"/><Metric label="External controls" value="Disabled"/></div><div className="rounded-xl border border-amber-500/30 bg-amber-500/5 p-5 text-sm text-amber-300">Configuration changes require deployment environment updates. This page intentionally does not expose secrets or provide client-side privilege-changing controls.</div></div>}

const pagePaths = {Dashboard:'/dashboard', 'Live Monitor':'/monitor', 'Network Monitor':'/network', Detections:'/detections', Alerts:'/alerts', Datasets:'/datasets', 'AI Models':'/models', 'Explainable AI':'/explainability', Analytics:'/analytics', Reports:'/reports', Settings:'/settings', Admin:'/admin', 'Network Reports':'/admin/network', Users:'/admin/users'};
function App(){
 const [path,setPath]=useState(window.location.pathname);
 const [user,setUser]=useState(null);
 const [checking,setChecking]=useState(Boolean(localStorage.getItem('access_token')));
 const [sessionError,setSessionError]=useState('');
 const [detail,setDetail]=useState(null);
 const navigate=(next,replace=false)=>{window.history[replace?'replaceState':'pushState']({},'',next);setPath(next);setDetail(null)};
 const loadUser=async()=>{const r=await api.get('/auth/me');setUser(r.data);setSessionError('');return r.data};
 const onLogin=async()=>{await loadUser();navigate('/dashboard',true)};
 useEffect(()=>{
   let active=true;
   const pop=()=>{setPath(window.location.pathname);setDetail(null)};
   const expired=()=>{active=false;setUser(null);setSessionError('');setChecking(false);navigate('/login',true)};
   window.addEventListener('popstate',pop);window.addEventListener('auth:logout',expired);
   if(localStorage.getItem('access_token')) api.get('/auth/me').then(r=>{if(active)setUser(r.data)}).catch(e=>{if(active && e.response?.status!==401)setSessionError(errorMessage(e,'Unable to verify your session. Please reload to try again.'))}).finally(()=>{if(active)setChecking(false)});
   return()=>{active=false;window.removeEventListener('popstate',pop);window.removeEventListener('auth:logout',expired)};
 },[]);
 const isAdmin=user?.role==='administrator';
 const isPublic=['/login','/signup','/register'].includes(path);
 const adminPath=path==='/admin'||path.startsWith('/admin/');
 useEffect(()=>{
   if(checking||sessionError)return;
   if(!user&&!isPublic)navigate('/login',true);
   else if(user&&(isPublic||path==='/'||(adminPath&&!isAdmin)))navigate('/dashboard',true);
 },[user,path,checking,sessionError]);
 if(checking)return <div role="status" className="min-h-screen bg-slate-950 p-8 text-slate-100">Verifying session…</div>;
 if(sessionError)return <div role="alert" className="min-h-screen bg-slate-950 p-8 text-red-300">{sessionError} <button onClick={logout}>Return to Login</button></div>;
 if(!user)return ['/signup','/register'].includes(path)?<SignupPage navigate={navigate}/>:<LoginPage onLogin={onLogin} navigate={navigate}/>;
 if(adminPath&&!isAdmin)return null;
 const page=Object.keys(pagePaths).find(key=>pagePaths[key]===path)||'Dashboard';
 const visibleNav=isAdmin?[...nav,'Admin','Network Reports','Users']:nav;
 const selectPage=(name)=>navigate(pagePaths[name]);
 const content=detail?<Details id={detail} back={()=>setDetail(null)}/>:page==="Admin"?<AdminOverview navigate={navigate} openDetection={setDetail}/>:page==="Network Reports"?<AdminNetworkReportsPanel />:page==="Users"?<AdminUsers currentUser={user}/>:page==="Dashboard"?<><DashboardPage openDetection={setDetail}/><div className="mt-6"><NetworkMonitorPage /></div></>:page==="Live Monitor"?<LiveMonitor openDetection={setDetail}/>:page==="Network Monitor"?<NetworkMonitorPage />:page==="Detections"?<DetectionsPage openDetection={setDetail}/>:page==="Alerts"?<AlertsPage openDetection={setDetail}/>:page==="Datasets"?<DatasetsPage/>:page==="AI Models"?<ModelsPage/>:page==="Explainable AI"?<ExplainableAIPage/>:page==="Analytics"?<AnalyticsPage/>:page==="Reports"?<ReportsPage openDetection={setDetail}/>:<SettingsPage/>;return <div className="min-h-screen bg-slate-950 text-slate-100"><aside className="fixed inset-y-0 left-0 hidden w-64 border-r border-slate-800 bg-slate-950 p-5 lg:block"><div className="mb-8"><div className="text-xs font-bold tracking-[.22em] text-cyan-400">AI-CTDRS</div><div className="mt-1 text-sm text-slate-400">Security Operations</div></div><nav className="space-y-1">{visibleNav.map(n=><button key={n} onClick={()=>{setDetail(null);selectPage(n)}} aria-current={page===n&&!detail?"page":undefined} className={`w-full rounded-lg px-3 py-2.5 text-left text-sm ${page===n&&!detail?"bg-cyan-500/10 text-cyan-300":"text-slate-400 hover:bg-slate-900 hover:text-white"}`}>{n}</button>)}</nav></aside><main className="lg:ml-64"><header className="sticky top-0 z-20 border-b border-slate-800 bg-slate-950/95 px-5 py-4 backdrop-blur"><div className="flex items-center justify-between"><div><div className="text-xs text-slate-500">AI-Driven Cyber Threat Detection and Response System</div><div className="font-semibold">{detail?"Detection Details":page}</div></div><div className="flex items-center gap-3"><select aria-label="Navigation" value={page} onChange={e=>{setDetail(null);selectPage(e.target.value)}} className="max-w-[150px] rounded-lg border border-slate-700 bg-slate-900 px-2 py-1.5 text-xs lg:hidden">{visibleNav.map(n=><option key={n}>{n}</option>)}</select><div className="hidden text-xs text-emerald-300 sm:block">Production API</div><button onClick={async()=>{try{await api.post("/auth/logout")}catch{}finally{logout()}}} className="rounded-lg border border-slate-700 px-3 py-1.5 text-xs text-slate-300 hover:bg-slate-800">Sign out</button></div></div></header><div className="p-5 lg:p-8">{content}</div></main></div>}
export default App;
